 session_start();require_once 'dbconn.php';require_once 'includes/functions.php';$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$identifier=trim($_POST['username']??'');if($identifier==='')$err='Enter your username or LRN.';else{try{$q=$pdo->prepare("SELECT user_id FROM users WHERE username=? AND role='Student' AND account_status='Active'");$q->execute([$identifier]);$uid=$q->fetchColumn();if(!$uid){$q=$pdo->prepare("SELECT user_id FROM users WHERE username=? AND role<>'System Administrator' AND account_status='Active'");$q->execute([$identifier]);$uid=$q->fetchColumn();}if($uid){$q=$pdo->prepare("SELECT request_id FROM password_reset_requests WHERE user_id=? AND request_status='Pending'");$q->execute([$uid]);if(!$q->fetchColumn()){$pdo->prepare("INSERT INTO password_reset_requests(user_id) VALUES(?)")->execute([$uid]);$registrars=$pdo->query("SELECT user_id FROM users WHERE role='School Registrar' AND account_status='Active'")->fetchAll(PDO::FETCH_COLUMN);$n=$pdo->prepare("INSERT INTO user_notifications(user_id,title,message,notification_type,related_url) VALUES(?,?,?,?,?)");foreach($registrars as $rid)$n->execute([$rid,'Password reset request','A user requested a password reset. Please review the request.','Password Reset','password_resets.php']);}}$msg='If the account exists, the Registrar has been notified. Please wait for the school to process your request.';}catch(Throwable $e){$err='Unable to submit the request. Please contact the school office.';}}}?>
